// ModelInfo - Power Query M
// Generated by src/powerbi_prep.py (STEP 11). Source: models/revenue_model_metadata.json, models/forecasting_metadata.json
// SYNTHETIC DATA. Change DataFolder once, in the DataFolder parameter, not here.
let
    Source = Csv.Document(
        File.Contents(DataFolder & "ModelInfo.csv"),
        [Delimiter = ",", Encoding = 65001, QuoteStyle = QuoteStyle.Csv]),
    Promoted = Table.PromoteHeaders(Source, [PromoteAllScalars = true]),
    Typed = Table.TransformColumnTypes(Promoted, {
        {"Model_Area", type text},
        {"Step", type text},
        {"Attribute", type text},
        {"Value", type text}
    }),
    Result = Typed
in
    Result
